const input = $input.first().json.output;

const PREFIXES = {
    business_requirements: "BR",
    functional_requirements: "FR",
    non_functional_requirements: "NFR",
    implicit_requirements: "IR",
    acceptance_criteria: "AC",
    business_rules: "RULE",
    dependencies: "DEP",
    constraints: "CON",
    assumptions: "ASM",
    ambiguities: "AMB",
    missing_information: "MISS",
    risks: "RISK",
    test_focus: "FOCUS"
};

const CONFIG = {

    confidence: {
        ambiguityPenalty: 3,
        missingPenalty: 2,
        assumptionPenalty: 1,
        acceptanceBonus: 1
    },

    maturity: {
        completenessWeight: 0.4,
        testabilityWeight: 0.3,
        confidenceWeight: 0.3
    },

    thresholds: {
        exploratoryTesting: 70,
        manualReview: 50
    }

};

const clamp = value => Math.max(0, Math.min(100, Math.round(value)));

const output = {};

// =========================
// Normalize arrays
// =========================

for (const [key, value] of Object.entries(input)) {

    if (key === "summary") {
        output.summary = value;
        continue;
    }

    if (key === "questions_by_role") {
        output.questions_by_role = value;
        continue;
    }

    if (!Array.isArray(value)) {
        output[key] = value;
        continue;
    }

    const prefix = PREFIXES[key] || key.toUpperCase();

    const unique = [...new Set(
        value
            .filter(v => typeof v === "string")
            .map(v => v.trim())
            .filter(v => v.length > 0)
    )];

    output[key] = unique.map((text, index) => ({
        id: `${prefix}-${index + 1}`,
        text
    }));
}

// =========================
// Statistics
// =========================

const statistics = {

    business_requirements:
        output.business_requirements?.length || 0,

    functional_requirements:
        output.functional_requirements?.length || 0,

    non_functional_requirements:
        output.non_functional_requirements?.length || 0,

    implicit_requirements:
        output.implicit_requirements?.length || 0,

    acceptance_criteria:
        output.acceptance_criteria?.length || 0,

    business_rules:
        output.business_rules?.length || 0,

    dependencies:
        output.dependencies?.length || 0,

    constraints:
        output.constraints?.length || 0,

    assumptions:
        output.assumptions?.length || 0,

    ambiguities:
        output.ambiguities?.length || 0,

    missing_information:
        output.missing_information?.length || 0,

    risks:
        output.risks?.length || 0,

    test_focus:
        output.test_focus?.length || 0,

    questions:
        Object.values(output.questions_by_role || {})
            .flat()
            .length
};

statistics.total_requirements =
    statistics.business_requirements +
    statistics.functional_requirements +
    statistics.non_functional_requirements +
    statistics.implicit_requirements +
    statistics.acceptance_criteria +
    statistics.business_rules;

// =========================
// Quality Metrics
// =========================

const confidenceScore = clamp(

    100

    - statistics.ambiguities * CONFIG.confidence.ambiguityPenalty

    - statistics.missing_information * CONFIG.confidence.missingPenalty

    - statistics.assumptions * CONFIG.confidence.assumptionPenalty

    + statistics.acceptance_criteria * CONFIG.confidence.acceptanceBonus

);

const completenessScore = clamp(

    (

        (

            (statistics.business_requirements > 0 ? 1 : 0) +

            (statistics.functional_requirements > 0 ? 1 : 0) +

            (statistics.non_functional_requirements > 0 ? 1 : 0) +

            (statistics.acceptance_criteria > 0 ? 1 : 0) +

            (statistics.business_rules > 0 ? 1 : 0) +

            (statistics.dependencies > 0 ? 1 : 0) +

            (statistics.constraints > 0 ? 1 : 0) +

            (statistics.risks > 0 ? 1 : 0)

        ) / 8

    ) * 100

);

const testabilityScore = clamp(

    40

    + statistics.acceptance_criteria * 2

    + statistics.business_rules

    + statistics.test_focus

    - statistics.missing_information

);

const requirementsMaturity = clamp(

    completenessScore * CONFIG.maturity.completenessWeight +

    testabilityScore * CONFIG.maturity.testabilityWeight +

    confidenceScore * CONFIG.maturity.confidenceWeight

);

const exploratoryTestingRecommended =

    requirementsMaturity < CONFIG.thresholds.exploratoryTesting ||

    statistics.ambiguities > 5 ||

    statistics.missing_information > 5;

const manualReviewRecommended =

    confidenceScore < CONFIG.thresholds.manualReview;

// =========================
// Metadata
// =========================

output.metadata = {

    schema_version: "2.0",

    generated_by: "Requirement Normalizer",

    generated_at: new Date().toISOString(),

    quality: {

        requirements_maturity: requirementsMaturity,

        confidence_score: confidenceScore,

        completeness_score: completenessScore,

        testability_score: testabilityScore,

        exploratory_testing_recommended: exploratoryTestingRecommended,

        manual_review_recommended: manualReviewRecommended

    },

    statistics

};

return [
    {
        json: output
    }
];

const input = $input.first().json;

