// Функция для рендеринга списка
const renderList = (items, emptyMessage = 'Нет данных') => {
    if (!items || !Array.isArray(items) || items.length === 0) {
        return `<div class="empty-state">${emptyMessage}</div>`;
    }
    return `<ul>${items.map(item => {
        if (typeof item === 'string') {
            return `<li>${item}</li>`;
        } else if (typeof item === 'object' && item !== null) {
            if (item.id && item.text) {
                return `<li><strong>${item.id}:</strong> ${item.text}</li>`;
            }
            const formatted = Object.entries(item)
                .map(([key, value]) => `<strong>${key}:</strong> ${value}`)
                .join(' | ');
            return `<li>${formatted}</li>`;
        }
        return `<li>${JSON.stringify(item, null, 2)}</li>`;
    }).join('')}</ul>`;
};

// Функция для рендеринга вопросов по ролям
const renderQuestions = (questionsObj) => {
    if (!questionsObj || typeof questionsObj !== 'object' || Object.keys(questionsObj).length === 0) {
        return '<div class="empty-state">Нет вопросов</div>';
    }
    let html = '';
    const roleLabels = {
        analyst: 'Аналитик',
        developer: 'Разработчик',
        product_owner: 'Владелец продукта',
        designer: 'Дизайнер',
        devops: 'DevOps'
    };
    for (const [role, qs] of Object.entries(questionsObj)) {
        if (Array.isArray(qs) && qs.length > 0) {
            const roleDisplay = roleLabels[role] || role.replace(/_/g, ' ').replace(/\b\w/g, l => l.toUpperCase());
