            background: #e67e22;
        }

        /* Responsive */
        @media (max-width: 900px) {
            .cards {
                grid-template-columns: repeat(2, 1fr);
            }
            .sections-grid {
                grid-template-columns: 1fr;
            }
            .sections-grid .section-full {
                grid-column: 1;
            }
            .pipeline-grid {
                grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
            }
