</head>

<body>

    <div class="container">

        <!-- Header -->
        <div class="header">
            <h1>📋 Requirement Review Dashboard</h1>
            <div class="subtitle">Анализ и проверка требований к системе</div>
            <div class="summary">
                <strong>📌 Резюме:</strong> ${summaryText}
            </div>
            <div class="status-summary">
                <div class="status-item">
                    <span class="status-dot completed"></span>
                    <span>✅ Done: ${Object.values(pipeline).filter(v => v.status === 'Completed').length}</span>
                </div>
                <div class="status-item">
                    <span class="status-dot pending"></span>
                    <span>⏳ Pending: ${Object.values(pipeline).filter(v => v.status === 'Pending').length}</span>
                </div>
            </div>
        </div>

        <!-- Quality Cards -->
        <div class="cards">
            ${renderQuality(quality)}
        </div>

        <!-- Statistics Table -->
        <div class="table">
            <h2>📊 Статистика по категориям</h2>
            <table>
                <thead>
                    <tr>
                        <th>Категория</th>
                        <th>Количество</th>
                    </tr>
                </thead>
                <tbody>
                    <tr>
                        <td class="category-name">Business Requirements</td>
                        <td class="category-value">${businessRequirements.length}</td>
                    </tr>
                    <tr>
                        <td class="category-name">Functional Requirements</td>
                        <td class="category-value">${functionalRequirements.length}</td>
                    </tr>
                    <tr>
                        <td class="category-name">Non Functional Requirements</td>
                        <td class="category-value">${nonFunctionalRequirements.length}</td>
                    </tr>
                    <tr>
                        <td class="category-name">Implicit Requirements</td>
                        <td class="category-value">${implicitRequirements.length}</td>
                    </tr>
                    <tr>
                        <td class="category-name">Acceptance Criteria</td>
                        <td class="category-value">${acceptanceCriteria.length}</td>
                    </tr>
                    <tr>
                        <td class="category-name">Business Rules</td>
                        <td class="category-value">${businessRules.length}</td>
                    </tr>
                    <tr>
                        <td class="category-name">Constraints</td>
                        <td class="category-value">${constraints.length}</td>
                    </tr>
                    <tr>
                        <td class="category-name">Assumptions</td>
                        <td class="category-value">${assumptions.length}</td>
                    </tr>
                    <tr>
                        <td class="category-name">Ambiguities</td>
                        <td class="category-value">${ambiguities.length}</td>
                    </tr>
                    <tr>
                        <td class="category-name">Missing Information</td>
                        <td class="category-value">${missingInformation.length}</td>
                    </tr>
                    <tr>
                        <td class="category-name">Risks</td>
                        <td class="category-value">${risks.length}</td>
                    </tr>
                    <tr>
                        <td class="category-name">Dependencies</td>
                        <td class="category-value">${dependencies.length}</td>
                    </tr>
                    <tr>
                        <td class="category-name">Questions</td>
                        <td class="category-value">${Object.values(questions).reduce((acc, curr) => acc + (Array.isArray(curr) ? curr.length : 0), 0)}</td>
                    </tr>
                    <tr>
                        <td class="category-name">Test Focus</td>
                        <td class="category-value">${testingFocus.length}</td>
                    </tr>
                </tbody>
            </table>
        </div>

        <!-- Requirements Sections -->
        <div class="sections-grid">
            <!-- Business Requirements -->
            <div class="section">
                <h2>📋 Business Requirements <span class="count">${businessRequirements.length}</span></h2>
                ${renderList(businessRequirements, 'Бизнес требования не указаны')}
            </div>

            <!-- Functional Requirements -->
            <div class="section">
                <h2>⚙️ Functional Requirements <span class="count">${functionalRequirements.length}</span></h2>
                ${renderList(functionalRequirements, 'Функциональные требования не указаны')}
            </div>

            <!-- Non Functional Requirements -->
            <div class="section">
                <h2>🔧 Non Functional Requirements <span class="count">${nonFunctionalRequirements.length}</span></h2>
                ${renderList(nonFunctionalRequirements, 'Нефункциональные требования не указаны')}
            </div>

            <!-- Implicit Requirements -->
            <div class="section">
                <h2>💡 Implicit Requirements <span class="count">${implicitRequirements.length}</span></h2>
                ${renderList(implicitRequirements, 'Неявные требования не указаны')}
            </div>

            <!-- Acceptance Criteria -->
            <div class="section section-full">
                <h2>✅ Критерии приемки <span class="count">${acceptanceCriteria.length}</span></h2>
                ${renderList(acceptanceCriteria, 'Критерии приемки не указаны')}
            </div>

            <!-- Business Rules -->
            <div class="section">
                <h2>📋 Бизнес правила <span class="count">${businessRules.length}</span></h2>
                ${renderList(businessRules, 'Бизнес правила не указаны')}
            </div>

            <!-- Dependencies -->
            <div class="section">
                <h2>🔗 Зависимости <span class="count">${dependencies.length}</span></h2>
                ${renderList(dependencies, 'Зависимости не указаны')}
            </div>

            <!-- Constraints -->
            <div class="section section-full">
                <h2>🔒 Ограничения <span class="count">${constraints.length}</span></h2>
                ${renderList(constraints, 'Ограничения не указаны')}
            </div>

            <!-- Assumptions -->
            <div class="section">
                <h2>🤔 Предположения <span class="count">${assumptions.length}</span></h2>
                ${renderList(assumptions, 'Предположения не указаны')}
            </div>

            <!-- Ambiguities -->
            <div class="section">
                <h2>❓ Неоднозначности <span class="count">${ambiguities.length}</span></h2>
                ${renderList(ambiguities, 'Неоднозначностей нет')}
            </div>

            <!-- Missing Information -->
            <div class="section section-full">
                <h2>⚠️ Недостающая информация <span class="count">${missingInformation.length}</span></h2>
                ${renderList(missingInformation, 'Недостающей информации нет')}
            </div>

            <!-- Risks -->
            <div class="section section-full">
                <h2>🚨 Риски <span class="count">${risks.length}</span></h2>
                ${renderList(risks, 'Риски не выявлены')}
            </div>

            <!-- Questions by Roles -->
            <div class="section section-full">
                <h2>❔ Вопросы к разным ролям <span class="count">${Object.values(questions).reduce((acc, curr) => acc + (Array.isArray(curr) ? curr.length : 0), 0)}</span></h2>
                ${renderQuestions(questions)}
            </div>

            <!-- Testing Focus -->
            <div class="section section-full">
                <h2>🎯 Фокус тестирования <span class="count">${testingFocus.length}</span></h2>
                ${renderList(testingFocus, 'Фокус тестирования не указан')}
            </div>
        </div>

        <!-- Recommendations -->
        ${recommendations.overall ? `
        <div class="recommendations">
            <h3>💡 Рекомендации</h3>
            <ul>
                ${recommendations.overall ? `<li><strong>Общая рекомендация:</strong> ${recommendations.overall}</li>` : ''}
                ${recommendations.exploratory_testing ? `<li><strong>Исследовательское тестирование:</strong> ${recommendations.exploratory_testing}</li>` : ''}
                ${recommendations.manual_review ? `<li><strong>Дополнительный review:</strong> ${recommendations.manual_review}</li>` : ''}
            </ul>
        </div>
        ` : ''}

        <!-- Pipeline Status -->
        <div class="section">
            <h2>⚙️ Pipeline Status</h2>
            <div class="pipeline-grid">
                ${Object.entries(pipeline).map(([key, value]) => {
                    const displayName = key.replace(/_/g, ' ').replace(/\b\w/g, l => l.toUpperCase());
                    const statusText = value.status === 'Completed' ? '✅ Done' : 
                                      value.status === 'Pending' ? '⏳ Pending' : 
                                      value.status === 'Ready' ? '🚀 Ready' : '⏳ Pending';
                    const statusClass = value.status === 'Completed' ? 'status-done' : 
                                       value.status === 'Pending' ? 'status-pending' : 
                                       value.status === 'Ready' ? 'status-ready' : 'status-pending';
                    return `
                        <div class="pipeline-item">
                            <span class="icon">${value.icon || '📦'}</span>
                            <span class="name">${displayName}</span>
                            <span class="status ${statusClass}">${statusText}</span>
                        </div>
                    `;
                }).join('')}
            </div>
        </div>

    </div>

</body>

</html>
`;

// ===== Преобразование HTML в binary для n8n =====
const htmlBuffer = Buffer.from(html, "utf8");

return [
  {
    json: {
      debug: {
        business_found: businessRequirements.length,
        functional_found: functionalRequirements.length,
        non_functional_found: nonFunctionalRequirements.length,
        acceptance_found: acceptanceCriteria.length,
        business_rules_found: businessRules.length,
        constraints_found: constraints.length,
        assumptions_found: assumptions.length,
        missing_found: missingInformation.length,
        risks_found: risks.length,
        questions_found: Object.keys(questions).length,
        testing_focus_found: testingFocus.length
      }
    },
    binary: {
      data: {
        data: htmlBuffer.toString("base64"),
        mimeType: "text/html",
        fileName: "RequirementReviewDashboard.html",
      },
    },
  },
];

